package main
import("fmt";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/mir2")
func main(){for _,kind:=range []string{"partialReturn","localArray"}{source:=&hir.Module{SourceUnitsComplete:true};actual:=&hir.Module{SourceUnitsComplete:true};f:=&hir.Func{Name:"f",RetTy:mir2.TyU8,Params:[]hir.Param{{Name:"flag",Ty:mir2.TyBool}}};var prefix,suffix []hir.Stmt;params:=[]hir.Param{};args:=[]hir.Expr{}
if kind=="partialReturn"{prefix=[]hir.Stmt{hir.If(hir.Var("flag",mir2.TyBool),hir.Blk(hir.Ret(hir.U8(7))),nil),&hir.ExprStmt{Expr:hir.U8(0)}};suffix=[]hir.Stmt{&hir.ExprStmt{Expr:hir.U8(1)},&hir.ExprStmt{Expr:hir.U8(2)}}}else{prefix=[]hir.Stmt{&hir.VarDeclStmt{Name:"a",Ty:mir2.TyU8,ArrayLen:2,Initial:[]hir.Expr{hir.U8(7),hir.U8(9)}},&hir.ExprStmt{Expr:hir.U8(0)}};suffix=[]hir.Stmt{hir.Ret(&hir.IndexExpr{Base:hir.Var("a",mir2.TyPtr),Idx:hir.U8(1),ElemTy:mir2.TyU8})};params=[]hir.Param{{Name:"a",Ty:mir2.TyU8}};args=[]hir.Expr{hir.Var("a",mir2.TyU8)}}
f.Body=hir.Blk(append(append([]hir.Stmt{},prefix...),suffix...)...);source.Funcs=[]*hir.Func{f};top:=*f;top.Body=hir.Blk(append(append([]hir.Stmt{},prefix...),hir.Ret(&hir.CallExpr{Fn:"f$split_1",Ty:mir2.TyU8,Args:args}))...);helper:=&hir.Func{Name:"f$split_1",Params:params,RetTy:mir2.TyU8,Body:hir.Blk(suffix...)};actual.Funcs=[]*hir.Func{&top,helper};actual.GraceRulePolicy=map[string]bool{};actual.PointerWalkPolicy=map[string]bool{};actual.InvariantBasePolicy=map[string]bool{};actual.ForwardCopyPolicy=map[string]bool{};_,e:=hir.ValidateRegionCompareCompiledChoices(source,actual,nil);fmt.Println(kind,"accepted",e==nil,"err",e);if kind=="localArray" {for _,m:=range []*hir.Module{source,actual} {vm:=mir2.NewVM(hir.LowerModule(m));r,err:=vm.Call("f",[]mir2.Value{{I:0}});fmt.Println("VM",r,err)}}}}
